const templates: Record<string, string> = {
  "ABDOMINAL CT SCAN": `<p><strong>ABDOMINAL CT SCAN</strong></p><p><strong>TECHNIQUE:</strong><br>Multiphase axial images of the abdomen obtained following oral and intravenous contrast administration, with multiplanar reconstructions.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Liver:</strong> Normal in size, contour, and attenuation. No focal lesions. Intrahepatic and extrahepatic bile ducts not dilated.</p></li><li><p><strong>Gallbladder and biliary tree:</strong> Normal. No stones, wall thickening, or pericholecystic fluid.</p></li><li><p><strong>Spleen:</strong> Normal in size, shape, and attenuation.</p></li><li><p><strong>Pancreas:</strong> Normal size and configuration, no focal mass, cyst, or peripancreatic inflammation.</p></li><li><p><strong>Adrenal glands:</strong> Normal morphology and attenuation.</p></li><li><p><strong>Kidneys and ureters:</strong> Normal in size, shape, and enhancement. No hydronephrosis, calculi, or focal lesions.</p></li><li><p><strong>Bowel:</strong> Stomach, small bowel, and colon normally distended and opacified. No wall thickening, obstruction, or abnormal enhancement. Appendix visualized and normal.</p></li><li><p><strong>Peritoneum/mesentery:</strong> No free fluid, free air, or abnormal collections.</p></li><li><p><strong>Vasculature:</strong> Abdominal aorta and major branches of normal caliber, no aneurysm or dissection. Normal venous structures.</p></li><li><p><strong>Lymph nodes:</strong> No abnormally enlarged lymph nodes.</p></li><li><p><strong>Bones and soft tissues:</strong> Normal.</p></li></ul><p><strong>IMPRESSION:</strong><br>Normal abdominal CT with oral and intravenous contrast.</p>`,

  "ABDOMINOPELVIC FEMALE": `<p><strong>ABDOMINO-PELVIC CT SCAN</strong></p><p><strong>TECHNIQUE:</strong><br>Multiphase axial CT images of the abdomen and pelvis were obtained following oral and intravenous contrast administration, with multiplanar reconstructions.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Liver:</strong> Normal in size, contour, and attenuation. No focal lesions. No intrahepatic or extrahepatic biliary dilatation.</p></li><li><p><strong>Gallbladder and biliary tree:</strong> Normal. No calculi, wall thickening, or pericholecystic changes.</p></li><li><p><strong>Spleen:</strong> Normal in size and attenuation.</p></li><li><p><strong>Pancreas:</strong> Normal size, contour, and enhancement. No focal mass, cyst, or peripancreatic inflammation.</p></li><li><p><strong>Adrenal glands:</strong> Normal morphology and attenuation bilaterally.</p></li><li><p><strong>Kidneys and ureters:</strong> Normal in size, shape, and enhancement. No hydronephrosis, calculi, or focal lesions.</p></li><li><p><strong>Bowel:</strong> Stomach, small bowel, and colon are normally distended and opacified. No wall thickening, obstruction, or abnormal enhancement. Appendix is normal.</p></li><li><p><strong>Urinary bladder:</strong> Well distended with normal wall thickness and contour.</p></li><li><p><strong>Uterus and adnexa:</strong> Normal size and morphology of the uterus, ovaries, and adnexa. No masses or cystic lesions.</p></li><li><p><strong>Peritoneum/mesentery:</strong> No free intraperitoneal fluid, free air, or abnormal collections.</p></li><li><p><strong>Lymph nodes:</strong> No abnormally enlarged abdominal or pelvic lymph nodes.</p></li><li><p><strong>Vasculature:</strong> Abdominal aorta and its branches are of normal caliber, no aneurysm or dissection. Venous structures are unremarkable.</p></li><li><p><strong>Bones and soft tissues:</strong> Visualized bony structures and soft tissues are intact, without suspicious lesions.</p></li></ul><p><strong>IMPRESSION:</strong><br>Normal abdomino-pelvic CT scan.</p>`,

  "ABDOMINOPELVIC MALE": `<p><strong>ABDOMINO-PELVIC CT SCAN</strong></p><p><strong>TECHNIQUE:</strong><br>Multiphase axial CT images of the abdomen and pelvis were obtained following oral and intravenous contrast administration, with multiplanar reconstructions.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Liver:</strong> Normal in size, contour, and attenuation. No focal lesions. No intrahepatic or extrahepatic biliary dilatation.</p></li><li><p><strong>Gallbladder and biliary tree:</strong> Normal. No calculi, wall thickening, or pericholecystic changes.</p></li><li><p><strong>Spleen:</strong> Normal in size and attenuation.</p></li><li><p><strong>Pancreas:</strong> Normal size, contour, and enhancement. No focal mass, cyst, or peripancreatic inflammation.</p></li><li><p><strong>Adrenal glands:</strong> Normal morphology and attenuation bilaterally.</p></li><li><p><strong>Kidneys and ureters:</strong> Normal in size, shape, and enhancement. No hydronephrosis, calculi, or focal lesions.</p></li><li><p><strong>Bowel:</strong> Stomach, small bowel, and colon are normally distended and opacified. No wall thickening, obstruction, or abnormal enhancement. Appendix is normal.</p></li><li><p><strong>Urinary bladder:</strong> Well distended with normal wall thickness and contour.</p></li><li><p><strong>Prostate and seminal vesicles:</strong> Normal size and morphology, no focal abnormality.</p></li><li><p><strong>Peritoneum/mesentery:</strong> No free intraperitoneal fluid, free air, or abnormal collections.</p></li><li><p><strong>Lymph nodes:</strong> No abnormally enlarged abdominal or pelvic lymph nodes.</p></li><li><p><strong>Vasculature:</strong> Abdominal aorta and its branches are of normal caliber, no aneurysm or dissection. Venous structures are unremarkable.</p></li><li><p><strong>Bones and soft tissues:</strong> Visualized bony structures and soft tissues are intact, without suspicious lesions.</p></li></ul><p><strong>IMPRESSION:</strong><br>Normal abdomino-pelvic CT scan.</p>`,

  "ANKLE MRI": `<p style="text-align: left;"><strong>ANKLE MRI</strong></p><p style="text-align: left;"><strong>TECHNIQUE:</strong></p><p style="text-align: left;">Multiplane PD, PD fat sat and T1 images were obtained through the … ankle.&nbsp;</p><p style="text-align: left;"><strong>FINDINGS:</strong></p><p style="text-align: left;"><u>General Findings:</u></p><ul><li><p style="text-align: left;">Marrow signal:&nbsp; &nbsp; normal</p></li><li><p style="text-align: left;">Alignment:&nbsp; &nbsp; normal</p></li></ul><p style="text-align: left;"><u>Medial Compartment:</u></p><ul><li><p style="text-align: left;">Medial malleolus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Posterior tibial tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Flexor digitorum longus tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Deltoid ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Spring ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Bifid ligament:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: left;"><u>Lateral Compartment:</u></p><ul><li><p style="text-align: left;">Lateral malleolus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Retromalleolar groove:&nbsp; flat</p></li><li><p style="text-align: left;">Peroneus tendons:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Peroneal retinaculum:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Tibiofibular ligaments:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Anterior talofibular ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Calcaneofibular ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Posterior talofibular ligament:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: left;"><u>Posterior Compartment:</u></p><ul><li><p style="text-align: left;">Posterior talus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Flexor hallucis longus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Distal tibiofibular syndesmosis:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Achilles tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Kager’s fat pad:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Plantar fascia:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: left;"><u>Anterior Compartment:</u></p><ul><li><p style="text-align: left;">Tibialis anterior tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Extensor hallucis longus:&nbsp; &nbsp; normal</p></li><li><p style="text-align: left;">Extensor digitorum longus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Peroneus tertius:&nbsp; &nbsp;absent</p></li></ul><p style="text-align: left;"><u>Joints:</u></p><ul><li><p style="text-align: left;">Tibiotalar joint:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Subtalar joint:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Tarsal joints:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: left;"><u>Other Findings:</u></p><ul><li><p style="text-align: left;">Bones:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Muscles:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Tarsal tunnel:&nbsp; &nbsp;normal</p></li><li><p style="text-align: left;">Sinus tarsi:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: left;"><strong>CONCLUSION:</strong></p><p style="text-align: left;">Normal ankle MRI.</p>`,

  "BILATERAL MAMMOGRAM": `<p><strong>BILATERAL BREAST MAMMOGRAM</strong></p><p><strong>TECHNIQUE:</strong></p><p>Standard bilateral craniocaudal (CC) and mediolateral oblique (MLO) views were obtained.</p><p>Images are of adequate quality with good compression and positioning.</p><p><strong>FINDINGS:</strong></p><ul><li><p>The breasts show scattered fibroglandular densities.</p></li><li><p>The parenchymal pattern is symmetrical bilaterally.</p></li><li><p>No discrete mass lesion, architectural distortion, or suspicious asymmetry identified in either breast.</p></li><li><p>No new focal density or spiculated lesion seen.</p></li><li><p>No suspicious microcalcifications or grouped calcifications identified.</p></li><li><p>No skin thickening, nipple retraction, or subareolar abnormality noted.</p></li><li><p>No axillary lymphadenopathy or abnormal soft tissue density seen bilaterally.</p></li></ul><p><strong>IMPRESSION</strong></p><p>Normal bilateral mammogram.</p><p>BI-RADS Category 1 – Negative.</p>`,

  "BRAIN ATROPHY": `<p><strong>BRAIN CT SCAN</strong></p><p><strong>Technique:</strong></p><p>Non-contrast axial CT images of the brain were obtained from the skull base to the vertex.</p><p><strong>FINDINGS:</strong></p><ul><li><p>There is generalized cortical and subcortical atrophy, evidenced by prominent cerebral sulci and widened Sylvian fissures. Mild ex vacuo dilatation of the ventricular system is seen.</p></li><li><p>There are periventricular white matter hypodensities, most prominent around the frontal and occipital horns of the lateral ventricles.</p></li><li><p>No focal parenchymal mass lesion, hemorrhage, or acute territorial infarct is identified.</p></li><li><p>Preserved gray-white matter differentiation.</p></li><li><p>Basal ganglia, thalami, brainstem and cerebellum are normal.</p></li><li><p>No midline shift, mass effect, or extra-axial collection.</p></li><li><p>Calvarium is intact with no lytic or sclerotic lesion.</p></li><li><p>Paranasal sinuses and mastoid air cells are well pneumatized with no significant mucosal thickening.</p></li></ul><p><strong>IMPRESSIONS:</strong></p><ol><li><p>Generalized brain - age-related involutional changes.</p></li><li><p>Periventricular white matter chronic ischemic changes, likely secondary to small vessel disease.</p></li><li><p>No acute intracranial hemorrhage, territorial infarction, or space-occupying lesion.</p></li></ol>`,

  "BRAIN CT": `<p><strong>BRAIN CT SCAN</strong></p><p><strong>TECHNIQUE</strong></p><p>Serial axial sections obtained from the skull base to the vertex, with multiplanar reconstructions.</p><p><strong>FINDINGS</strong></p><ul><li><p>Brain parenchyma is normal in attenuation.</p></li><li><p>No focal SOL, dural spaces are clear.</p></li><li><p>Grey – white matter differentiation is preserved.</p></li><li><p>Ventricular system is normal.</p></li><li><p>No midline shift.</p></li><li><p>Both thalami, basal ganglia and midbrain structures are normal</p></li><li><p>Paranasal sinuses are clear.</p></li><li><p>Calvarium is normal.</p></li><li><p>Both mastoids are normal.</p></li></ul><p><strong>IMPRESSION</strong></p><p>Normal Head CT study.</p>`,

  "BRAIN CT ANGIOGRAM I": `<p><strong>BRAIN CT ANGIOGRAM</strong></p><p><strong>PROCEDURE:</strong><br>CT angiography of the head and neck was performed following intravenous contrast administration. Arterial-phase images were acquired with multiplanar reconstructions in axial, coronal, and sagittal planes.&nbsp;</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Intracranial circulation:</strong> The anterior and posterior circulations, including the bilateral internal carotid arteries, vertebral arteries, basilar artery, and their intracranial branches (including ACA, MCA, PCA), are patent and demonstrate normal course, caliber, and enhancement. No evidence of aneurysm, stenosis, vascular malformation, or arterial dissection is seen.</p></li><li><p><strong>Extra-cranial circulation:</strong> The common, internal, and external carotid arteries and vertebral arteries are well opacified bilaterally with no evidence of stenosis, dissection, or aneurysmal dilatation.</p></li><li><p><strong>No abnormal tangle of vessels</strong>, nidus formation, or arteriovenous shunting to suggest an AVM is identified.</p></li></ul><p><strong>IMPRESSION:</strong></p><ul><li><p><strong>Normal CT angiogram</strong></p></li><li><p><strong>No evidence of AVM/AVF or other vascular abnormality.</strong></p></li></ul>`,

  "BRAIN CT ANGIOGRAM II": `<p><strong>CT SCAN BRAIN ANGIOGRAM</strong></p><p><strong>FINDINGS</strong></p><ul><li><p>The common carotid arteries are normal.</p></li><li><p>Right and left external carotid arteries are normal.</p></li><li><p>The right and left internal carotid arteries are normal.</p></li><li><p>The basilar artery is normal.</p></li><li><p>Posterior circulation arteries are normal.</p></li><li><p>The posterior communicating artery is normal.</p></li><li><p>The middle cerebral arteries are normal.</p></li><li><p>The anterior cerebral arteries re normal.</p></li><li><p>The anterior communicating artery is normal.</p></li><li><p>The carotid atrial branches are normal.</p></li></ul><p><strong>IMPRESSION</strong></p><ul><li><p>Normal Brain Angiogram CT study</p></li></ul>`,

  "BRAIN CT WITHOUT CONTRAST": `<p><strong>BRAIN CT SCAN</strong></p><p><strong>TECHNIQUE:</strong><br>Serial axial sections obtained from the skull base to the vertex, with multiplanar reconstructions.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Cerebral parenchyma:</strong> Normal attenuation. No focal mass lesion, hemorrhage, or infarction identified.</p></li><li><p><strong>Gray–white matter differentiation:</strong> Preserved.</p></li><li><p><strong>Ventricular system and sulci:</strong> Normal in size and configuration, appropriate for age. No hydrocephalus or midline shift.</p></li><li><p><strong>Basal cisterns:</strong> Patent.</p></li><li><p><strong>Extra-axial spaces:</strong> No abnormal collections.</p></li><li><p><strong>Calvarium and skull base:</strong> Intact, no fractures or destructive lesions.</p></li><li><p><strong>Visualized paranasal sinuses and mastoid air cells:</strong> Clear.</p></li><li><p><strong>Orbits:</strong> Appear unremarkable.</p></li></ul><p><strong>IMPRESSION:</strong><br>Unremarkable non-contrast CT brain study.</p>`,

  "BRAIN MRI": `<p><strong>BRAIN MRI</strong></p><p><strong>TECHNIQUE:</strong><br>Multiplanar, multisequence MRI images of the brain were obtained without intravenous contrast administration.</p><p><strong>FINDINGS:</strong></p><ul><li><p>No intra- or extra-axial mass lesion or collection is identified. The ventricles and sulcal spaces are within normal limits. The midline structures are normal with no midline shift.</p></li><li><p>The brain parenchyma is unremarkable without evidence of demyelinating lesions.&nbsp;</p></li><li><p>No abnormal signal on the diffusion/ADC images is identified.</p></li><li><p>The pituitary gland is normal.</p></li><li><p>Both intra and extraconal spaces are normal in appearance.</p></li><li><p>Normal optic nerves, orbital apex, chiasm and optic radiations.</p></li><li><p>Cavernous sinus unremarkable.</p></li><li><p>The paranasal sinuses and mastoid air cells are otherwise clear.</p></li><li><p>No bony abnormality is seen.&nbsp;</p></li><li><p>The craniocervical junction is normal.</p></li></ul><p><strong>IMPRESSION:</strong><br>Normal non-contrast MRI brain.</p>`,

  "C SPINE CT": `<p><strong>CERVICAL SPINE CT SCAN</strong></p><p><strong>TECHNIQUE:</strong></p><p>Fine slice non-contrast helical CT images were obtained from the skull base to the thoracic inlet. Bone and soft windows were reconstructed.</p><p><strong>FINDINGS:</strong></p><ul><li><p>No fractures or other bony abnormalities are identified in the cervical spine. The vertebral bodies and discs are of normal height with no malalignment. No disc bulges are identified.</p></li><li><p>The facet and uncovertebral joints have a normal appearance.</p></li><li><p>The craniocervical junction is unremarkable, with normal foramen magnum.</p></li><li><p>The spinal canal is widely patent with normal appearing cord. The neural exit foramina are normal.</p></li><li><p>No paravertebral abnormality is seen. The prevertebral space is normal. The neurovascular structures and muscles are normal. No lymphadenopathy is seen.</p></li><li><p>The lung apices are normal.</p></li></ul><p><strong>CONCLUSION:</strong></p><p>Normal CT cervical spine.</p>`,

  "C SPINE MRI": `<p><strong><u>CERVICAL SPINE MRI</u></strong></p><p><strong><u>TECHNIQUE:</u></strong></p><p>Multiplanar multisequential MRI of the cervical spine were provided without IV contrast.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Maintained normal cervical spine lordosis.</p></li><li><p>Adequate alignment of the cervical spine, with no signs of instability detected.</p></li><li><p>Normal marrow signal of the cervical vertebrae, with no focal lesions identified.</p></li><li><p>Normal signal intensity of cervical disc.&nbsp;</p></li><li><p>No significant disc bulges or herniations seen, with no cord or foraminal compromise visualized.</p></li><li><p>Normal shape, girth and intensity of the cervical cord, with no cervico-medullary junction abnormalities noted.</p></li><li><p>No bony canal tightness observed.</p></li><li><p>Normal pre and paravertebral soft tissue shadow.</p></li></ul><p><strong><u>IMPRESSION:</u></strong></p><p><strong>Normal cervical spine MRI.</strong></p>`,

  "CHEST ABDOMEN CT": `<p><strong>CHEST AND ABDOMEN CT</strong></p><p><strong>CHEST FINDINGS</strong></p><ul><li><p>Both lung fields are clear.</p></li><li><p>There are no pulmonary nodules seen.</p></li><li><p>There is no pleural effusion.</p></li><li><p>Normal pleura, no thickening.</p></li><li><p>The heart and the great mediastinal vessels are normal.</p></li><li><p>There is no hilar adenopathy.</p></li><li><p>No mediastinal adenopathy.</p></li><li><p>The vertebral bones and other bony structures are normal, no metastasis.</p></li><li><p>Normal subcutaneous tissues</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Normal CT chest findings.</p></li></ol><p><strong>ABDOMEN FINDINGS</strong></p><ul><li><p>The liver is of normal attenuation. No focal parenchymal lesion</p></li><li><p>The GB and biliary ducts are of normal caliber. No gall stones or biliary dilatation</p></li><li><p>The spleen is homogeneous and normal in size</p></li><li><p>The pancreas is of normal attenuation and size.</p></li><li><p>Both kidneys opacify well and excrete IV contrast normally. No hydronephrosis. No renal calculi. Corticomedullary differentiation is well maintained.</p></li><li><p>Bowel loops are of normal caliber.</p></li><li><p>Urinary bladder has smooth walls. No bladder masses or calculi.</p></li><li><p>No pelvic masses seen.</p></li><li><p>No ascites. No para-aortic adenopathy.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Normal abdominal CT Scan.</p></li></ol>`,

  "CHEST CT NONCONTRAST": `<p><strong>CHEST CT SCAN</strong><br><strong><u>Technique</u></strong></p><p>A non-contrast axial CT scan of the chest was obtained, including multiplanar reformatted images.</p><p><strong><u>Findings&nbsp;</u></strong></p><p>The lung fields are clear bilaterally, with no evidence of focal consolidation, ground-glass opacities, pulmonary nodules, or interstitial abnormalities. The pleural spaces are unremarkable, with no effusion or pneumothorax identified.</p><p>The mediastinum and hila are within normal limits. The heart and great vessels demonstrate normal size and configuration. There is no evidence of mediastinal or hilar lymphadenopathy. The trachea and main bronchi are patent and midline, without endobronchial lesions.</p><p>The bony thorax, including the visualized ribs, sternum, and spine, shows no fractures, destructive lesions, or abnormal sclerotic or lytic changes. The chest wall soft tissues are unremarkable.</p><p>Incidental portions of the upper abdomen are visualized and appear normal, with no masses, fluid collections, or organomegaly.</p><p><strong><u>Conclusion:</u></strong><br>Normal non-contrast CT scan of the chest. No pulmonary, pleural, mediastinal, or chest wall abnormalities identified.</p><p><br></p>`,

  "CHEST HRCT": `<p style="text-align: justify;"><strong>CHEST HRCT</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Fine slice non-contrast helical CT images were obtained from the lung apices to the lung bases. Mediastinal and lung windows were reconstructed.&nbsp;</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><ul><li><p>The pulmonary parenchyma has a normal appearance, with no nodules, ground-glass change, collapse, consolidation or emphysematous/cystic change seen.</p></li><li><p style="text-align: justify;">The pulmonary vessels and bronchi are normal.</p></li><li><p style="text-align: justify;">The heart, great vessels, trachea and oesophagus have a normal appearance. There is no lymphadenopathy.</p></li><li><p style="text-align: justify;">The pleural spaces are clear. No effusion or thickening.</p></li><li><p style="text-align: justify;">The upper abdominal solid organs and bowel have a normal non-contrast appearance within the field of view.</p></li><li><p style="text-align: justify;">No bony abnormality is identified.</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><p style="text-align: justify;"><strong>Normal HRCT Chest.</strong></p>`,

  "CHEST XRAY": `<p><strong>CHEST X-RAY</strong></p><p><strong>TECHNIQUE:</strong></p><p>PA view of the chest.&nbsp;</p><p><strong>FINDINGS</strong></p><ul><li><p>The lung fields are clear.</p></li><li><p>Pulmonary vascular pattern is normal.</p></li><li><p>The hilar and peri-hilar regions are normal.</p></li><li><p>Both costophrenic angles are clear. No free fluid or free gas.</p></li><li><p>Cardiac shadow is normal in size and morphology.</p></li><li><p>The thoracic bone cage and thoracic vertebral spine are normal.</p></li><li><p>No fracture seen.</p></li><li><p>Area under the diaphragm is normal.</p></li></ul><p><strong>CONCLUSION</strong></p><p>Normal chest radiograph.</p>`,

  "CN VII AND VIII MRI": `<p><strong>CN VII AND VIII MRI SCAN</strong></p><p><strong>TECHNIQUE</strong></p><p>Multiplanar, multisequence MRI of the cerebellopontine angle was performed without and with IV contrast including high-resolution images through the course of both VII and VIII cranial nerves.</p><p><strong>FINDINGS</strong></p><ul><li><p>There is no focal brain parenchymal signal abnormality. In particular, the midbrain and brainstem are normal.</p></li><li><p>The major arterial flow voids and dural venous sinuses are normal.</p></li><li><p>The external acoustic canal, middle ear, vestibular-cochlear apparatus and internal acoustic canals have a normal appearance.</p></li><li><p>The facial and vestibulocochlear nerves have a normal appearance, with no focal lesion, signal abnormality or abnormal enhancement.</p></li><li><p>The geniculate ganglion, cochlear component and descending bony component of the facial nerve have a normal appearance bilaterally.</p></li><li><p>The trigeminal and abducens nerves have a normal appearance.</p></li><li><p>Both parotid glands display normal signal.</p></li><li><p>The base of skull is normal. The mastoid air cells are clear.</p></li><li><p>The paranasal sinuses are well aerated.</p></li></ul><p><strong>CONCLUSION</strong></p><p>Normal MRI study: No MR evidence of intracranial pathology.</p>`,

  COMPILED: `<p><strong>HEAD FINDINGS</strong></p><ul><li><p>Brain parenchyma is normal in attenuation.</p></li><li><p>No focal SOL, dural spaces are clear.</p></li><li><p>Grey – white matter differentiation is preserved.</p></li><li><p>Ventricular system appears normal.</p></li><li><p>No midline shift.</p></li><li><p>Both thalami, basal ganglia and midbrain structures appear normal.</p></li><li><p>Paranasal sinus, mastoid air cells appear normal.</p></li><li><p>Calvarium appears normal.</p></li><li><p>Both mastoids are normal.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Normal Head CT study</p></li></ol><p><strong>NECK FINDINGS</strong></p><ul><li><p>Normal nasopharyngeal space.</p></li><li><p>Normal oropharynx, oral cavity, parapharyngeal and retropharyngeal space.</p></li><li><p>Normal larynx, hypopharynx and supraglottic.</p></li><li><p>Normal thyroid.</p></li><li><p>No cervical lymphadenopathy.</p></li><li><p>Normal vascular structures.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Normal Neck CT scan.</p></li></ol><p><strong>CHEST FINDINGS</strong></p><ul><li><p>Both lung fields are clear.</p></li><li><p>There are no pulmonary nodules seen.</p></li><li><p>There is no pleural effusion.</p></li><li><p>Normal pleura, no thickening.</p></li><li><p>The heart and the great mediastinal vessels are normal.</p></li><li><p>There is no hilar adenopathy.</p></li><li><p>No mediastinal adenopathy.</p></li><li><p>The vertebral bones and other bony structures are normal, no metastasis.</p></li><li><p>Normal subcutaneous tissues.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Normal CT chest findings.</p></li></ol><p><strong>ABDOMEN FINDINGS</strong></p><ul><li><p>The liver is of normal attenuation. No focal parenchymal lesion.</p></li><li><p>The GB and biliary ducts are of normal caliber. No gall stones or biliary dilatation.</p></li><li><p>The spleen is homogeneous and normal in size.</p></li><li><p>The pancreas is of normal attenuation and size.</p></li><li><p>Both kidneys opacify well and excrete IV contrast normally. No hydronephrosis. No renal calculi. Corticomedullary differentiation is well maintained.</p></li><li><p>Bowel loops are of normal caliber.</p></li><li><p>Urinary bladder has smooth walls. No bladder masses or calculi.</p></li><li><p>No pelvic masses seen.</p></li><li><p>No ascites. No para-aortic adenopathy.</p></li></ul><p>IMPRESSION</p><ol><li><p>Normal abdominal CT Scan.</p></li></ol>`,

  "CT AORTOGRAM": `<p><strong>CT AORTOGRAM</strong></p><p><strong>TECHNIQUE:</strong></p><p>CT aortogram performed following intravenous contrast administration. Multiplanar reformatted images were reviewed in arterial and soft-tissue windows.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Aorta:</strong></p><ul><li><p>The thoracic and visualized abdominal aorta demonstrate normal caliber, contour, and homogeneous opacification without evidence of dissection, aneurysm, intramural hematoma, or penetrating ulcer.</p></li><li><p>No mural thrombus, atherosclerotic plaque, or periaortic inflammatory changes noted.</p></li></ul></li><li><p><strong>Aortic measurements:</strong></p><ul><li><p>Sinus of Valsalva: 40 mm (Normal: 29–45 mm)</p></li><li><p>Sino-tubular junction: 33.2 mm (Normal: 22–36 mm)</p></li><li><p>Ascending aorta: 29 mm (Normal: 22–36 mm)</p></li><li><p>Aortic arch: 30.2 mm (Normal: 22–36 mm)</p></li><li><p>Proximal descending thoracic aorta: 28 mm (Normal: 20–30 mm)</p></li><li><p>Distal descending thoracic aorta: 28 mm (Normal: 20–30 mm)</p></li><li><p>Proximal intra-abdominal aorta: 26.6 mm</p></li></ul></li><li><p><strong>Branch vessels:</strong></p><ul><li><p>Aortic arch branches (brachiocephalic, left common carotid, left subclavian): Normal origins, caliber, and contrast opacification.</p></li><li><p>Celiac trunk and superior mesenteric artery: Patent, normal origins and opacification.</p></li><li><p>Renal arteries: Normal course, caliber, and opacification.</p></li><li><p>Inferior mesenteric artery: Patent and normal.</p></li><li><p>Iliac arteries: Not included within the imaged field.</p></li></ul></li></ul><p><strong>OTHER FINDINGS</strong></p><ul><li><p>Heart is normal in size and configuration with no pericardial effusion or thickening.</p></li><li><p>Pulmonary arteries, superior vena cava, azygos and innominate veins are normal. No filling defect seen.</p></li></ul><p><strong>IMPRESSION</strong></p><p><strong>Normal CT aortogram - no evidence of aneurysm, dissection, or other aortic pathology.</strong></p>`,

  "CT KUB NORMAL": `<p><strong>CT KUB</strong></p><p><strong>TECHNIQUE</strong></p><p>Fine slice non-contrast helical CT images were obtained from the tops of the kidneys to the perineum.</p><p><strong>FINDINGS</strong></p><ul><li><p>Both kidneys have a normal appearance with no perinephric fat stranding. The pelvicalyceal systems are normal with no calculi identified. The right kidney measure … x … x … cm and the left … x … x … cm.</p></li><li><p>Both ureters and the bladder are normal. No calculi seen.</p></li><li><p>The solid organs have a normal appearance for a non-contrast study. The bowel is unremarkable.</p></li><li><p>No free fluid or gas is seen in the abdomen or pelvis. No lymphadenopthy is identified.</p></li><li><p>The lung bases are clear. No bony abnormality is seen.</p></li></ul><p><strong>CONCLUSION</strong></p><p>Normal CT KUB</p>`,

  "CT PELVIS": `<p><strong>CT PELVIS</strong></p><p><strong>CLINICAL NOTE:</strong></p><p>Post-trauma. ? <strong>sacroiliac joint dislocation.</strong></p><p><strong>TECHNIQUE:</strong></p><p>Non-contrast axial CT scan of the pelvis was performed with 3D reconstruction for bony evaluation.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Sacroiliac joints: Both sacroiliac joints are well aligned, with preserved joint spaces and no evidence of dislocation or subluxation.</p></li><li><p>Pelvic bones: Iliac wings, sacrum, ischium, and pubic rami are intact with no fractures, cortical irregularity, or bony displacement.</p></li><li><p>Hip joints: Bilateral hip joints are anatomically aligned with normal joint spaces and no fracture or effusion.</p></li><li><p>Acetabula: Symmetrical and intact.</p></li><li><p>Pelvic organs: Urinary bladder, rectum and visualized small bowel loops are normal.</p></li><li><p>Soft tissues: Appear unremarkable. No hematoma, gas collection, or foreign body identified.</p></li></ul><p><strong>Impression</strong></p><p><strong>Normal CT scan of the pelvis. No sacroiliac joint dislocation or pelvic fracture identified.</strong></p>`,

  "CT RENAL ANGIOGRAM": `<p><strong>CT RENAL ANGIOGRAM</strong></p><p><strong>INDICATION: </strong>Potential living kidney donor.</p><p><strong>TECHNIQUE:</strong><br>Multidetector CT angiography of the abdomen was performed following intravenous contrast administration. Arterial and venous phase images were acquired. MPR done.</p><p><strong>FINDINGS:</strong></p><p><strong>Renal Arteries:</strong></p><ul><li><p><strong>Right Kidney:</strong></p><ul><li><p>Supplied by single main right renal artery<strong> </strong>with no accessory artery, both arising directly from the abdominal aorta.</p></li><li><p>Main right renal artery: Length: 3.2 cm&nbsp;</p><ul><li><p>Ostial diameter: 4.4<strong>&nbsp;</strong>mm</p></li><li><p>Mid-segment diameter: 3.3&nbsp;mm</p></li></ul></li></ul></li><li><p><strong>Left Kidney:</strong></p><ul><li><p>Supplied by a main left renal artery and no<strong> </strong>accessory left renal artery, both arising from the aorta.</p></li><li><p>Main left renal artery: length: 3.0 cm</p><ul><li><p>Ostial diameter: 4.1 mm</p></li><li><p>Mid-segment diameter: 3.4&nbsp;mm</p></li></ul></li></ul></li><li><p>No evidence of arterial stenosis, dissection, aneurysm, or vascular calcification.</p></li></ul><p><strong>Renal Veins:</strong></p><ul><li><p><strong>Right renal vein:</strong></p><ul><li><p>Drains directly into the inferior vena cava.</p></li><li><p>Diameter at confluence with IVC: 10.8 mm</p></li><li><p>No duplication, thrombus, or compression.</p></li></ul></li><li><p><strong>Left renal vein:</strong></p><ul><li><p>Courses anterior to the aorta and posterior to the superior mesenteric artery before draining into the IVC.</p></li><li><p>Diameter at confluence with IVC: 10.5<strong>&nbsp;</strong>mm</p></li><li><p>No compression or nutcracker phenomenon.</p></li></ul></li></ul><p><strong>Kidneys:</strong></p><ul><li><p><strong>Right kidney:</strong>&nbsp;10 x 4.7 cm</p></li><li><p><strong>Left kidney:</strong>&nbsp;10.3 x 4.5 cm</p></li><li><p>Both kidneys demonstrate symmetric enhancement and preserved corticomedullary differentiation.</p></li><li><p>No focal masses, stones, or hydronephrosis.</p></li></ul><p><strong>OTHER FINDINGS:</strong></p><ul><li><p>Abdominal aorta and its branches are patent.&nbsp;No&nbsp;atherosclerosis or aneurysmal dilation.</p></li><li><p>Liver, spleen, pancreas, adrenal glands, and bowel loops appear unremarkable.</p></li></ul><p><strong>CONCLUSION:</strong></p><ol><li><p><strong>Both kidneys supplied by a single renal artery arising directly from the abdominal aorta.</strong></p></li><li><p><strong>Renal veins are single, of adequate caliber, and drain normally into the IVC.</strong></p></li><li><p><strong>No vascular or renal parenchymal abnormalities detected.</strong></p></li></ol>`,

  CTPA: `<p><strong>CT PULMONARY ANGIOGRAM (CTPA)</strong></p><p><strong>TECHNIQUE:</strong><br>CTPA performed following IV administration of iodinated contrast using a dedicated PE protocol with bolus tracking at the main pulmonary artery. Axial, coronal, and sagittal reconstructions were reviewed.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Pulmonary arteries</strong>: No intraluminal filling defects are seen throughout the main, lobar, segmental, or subsegmental branches of the pulmonary arteries bilaterally to suggest pulmonary embolism. Normal opacification and caliber of the pulmonary arterial tree. No evidence of pulmonary arterial hypertension; the pulmonary trunk measures within normal limits.</p></li><li><p><strong>Lungs and airways</strong>: Normal.&nbsp;</p></li><li><p><strong>Pleural spaces</strong>: No pleural effusion or pneumothorax.</p></li><li><p><strong>Mediastinum and hilae</strong>: Normal appearance of the mediastinum. No mediastinal or hilar lymphadenopathy. Normal size and appearance of the aorta and its branches. No aneurysm or dissection. Normal course and caliber of the superior vena cava and azygos vein.</p></li><li><p><strong>Heart and pericardium</strong>: Normal cardiac size and configuration. No pericardial effusion. No signs of right heart strain.</p></li><li><p><strong>Chest wall</strong>: No suspicious osseous lesions. No chest wall abnormality.&nbsp;</p></li><li><p><strong>Upper abdomen:</strong> Visualized portions of the upper abdomen are unremarkable.&nbsp;</p></li></ul><p><strong>IMPRESSION:</strong></p><ol><li><p><strong>No evidence of pulmonary embolism.</strong></p></li><li><p><strong>Normal CTPA.</strong><br></p></li></ol>`,

  "FACIAL BONE CT": `<p><strong>FACIAL BONE CT</strong></p><p><strong>TECHNIQUE:</strong></p><p>Fine slice non-contrast helical CT images were obtained through the facial bones. Soft tissue and bone windows were reconstructed.</p><p><strong>FINDINGS:</strong></p><ul><li><p>No fractures or bony abnormalities are identified in the facial bones.</p></li><li><p>The zygomatic arch is normal and there is no diastasis of the frontozygomatic suture. The orbital rim is intact, as are the nasal bones.</p></li><li><p>The paranasal sinuses are clear with no mucoperiosteal thickening. The nasal septum is midline with no spur. The osteomeatal complexes are normal.</p></li><li><p>The orbits have a normal appearance with unremarkable: globes, optic nerves, extra-ocular muscles, infraorbital canal, superior and inferior orbital foramina, optic canal and lamina papyracea.</p></li><li><p>The pterygoid plates and pterygopalatine fossa are normal.</p></li><li><p>The inferior alveolar ridge is normal.</p></li><li><p>The mandible is unremarkable with normal temporomandibular joints.</p></li><li><p>The visualized nasopharynx has a normal appearance.</p></li><li><p>No contusion or other soft tissue swelling is seen.</p></li></ul><p><strong>CONCLUSION:</strong></p><p>Normal CT facial bones.</p>`,

  "FOOT MRI SHORT": `<p><strong>FOOT MRI</strong></p><p><strong>PROCEDURE</strong></p><p>Multisequential multiplanar MRI of the foot.</p><p><strong>FINDINGS</strong></p><ul><li><p>The flexor and extensor and peroneus tendons are normal. Normal muscle bulk and signal intensity.</p></li><li><p>Normal tarsal, metartarsal and phallangeal bones with intact articulations.</p></li><li><p>The foot joint spaces are normal with regular articular margins throughout.</p></li><li><p>Ankle mortise and syndesmosis are intact and of normal MR signal intensity.</p></li><li><p>The ankle joint ligaments are intact.</p></li><li><p>Normal articular cartilages.</p></li><li><p>Normal sinus tarsi.</p></li><li><p>Achilles tendon is normal in contour, thickness and signal.</p></li><li><p>No joint effusions.</p></li><li><p>No fracture. No dislocation.</p></li></ul><p><strong>CONCLUSION</strong></p><p>Normal foot MRI</p>`,

  "FOOT MRI DETAILED": `<p style="text-align: justify;"><strong>FOOT MRI</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Multiplane T1 and T2 inversion recovery imaging was obtained through the … foot.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><p style="text-align: justify;"><u>Bones:</u></p><ul><li><p style="text-align: justify;">Marrow: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Alignment: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Longitudinal plantar arch: &nbsp; Normal.</p></li></ul><p style="text-align: justify;"><u>Joints:</u></p><ul><li><p style="text-align: justify;">Ankle joint: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Intertarsal joints: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Tarsometatarsal joints: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Metatarsophalangeal and interphalangeal joints: &nbsp;Normal.</p></li></ul><p style="text-align: justify;"><u>Ligaments:</u></p><ul><li><p style="text-align: justify;">Bifid ligament: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Spring ligaments: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Talocalcaneal ligament: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Dorsal talonavicular ligament: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Intertarsal ligaments: &nbsp; Normal&nbsp;</p></li><li><p style="text-align: justify;">Plantar aponeurosis: &nbsp; Normal.</p></li></ul><p style="text-align: justify;"><u>Tendons:</u></p><ul><li><p style="text-align: justify;">Flexor tendons: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Extensor tendons: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Perineal tendons: &nbsp; Normal</p></li></ul><p style="text-align: justify;"><u>Soft tissues:</u></p><ul><li><p style="text-align: justify;">Muscles: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Neurovascular structures: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Sinus tarsi: &nbsp; Normal.</p></li><li><p style="text-align: justify;">Tarsal tunnel: &nbsp; Normal</p></li><li><p style="text-align: justify;">Other: &nbsp; Normal.</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><p style="text-align: justify;">Normal foot MRI.</p>`,

  "HIP MRI": `<p style="text-align: justify;"><strong>HIP MRI</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Multiplanar multisequential Hip MRI using a 1.5 T closed magnet machine.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><p style="text-align: justify;"><u>Bones:</u></p><ul><li><p style="text-align: justify;">No evidence of fracture or bone oedema is seen.</p></li><li><p style="text-align: justify;">No femoral head changes to suggest avascular necrosis</p></li><li><p style="text-align: justify;">No focal bony lesion is seen.</p></li><li><p style="text-align: justify;">No evidence of femoro-acetabular impingement</p></li></ul><p style="text-align: justify;"><u>Cartilage and Labrum:</u></p><ul><li><p style="text-align: justify;">No joint space narrowing is seen.</p></li><li><p style="text-align: justify;">No evidence of altered cartilage signal is identified to suggest chondromalacia or delamination</p></li><li><p style="text-align: justify;">The labrum has a normal appearance with no tear identified.</p></li><li><p style="text-align: justify;">No paralabral cyst is seen.</p></li><li><p style="text-align: justify;">Ligamentum Teres is normal</p></li></ul><p style="text-align: justify;"><u>Effusion:</u></p><ul><li><p style="text-align: justify;">No joint effusion</p></li><li><p style="text-align: justify;">The trochanteric bursa is normal</p></li></ul><p style="text-align: justify;"><u>Muscles and tendons:</u></p><ul><li><p style="text-align: justify;">No muscle abnormality is seen around the ___ hip joint.</p></li><li><p style="text-align: justify;">Iliopsoas muscle and tendon:&nbsp; Normal.</p></li><li><p style="text-align: justify;">The gluteal musculature and tendons: Normal.</p></li><li><p style="text-align: justify;">The iliotibial muscle and tendon: Normal</p></li><li><p style="text-align: justify;">The adductor muscles and tendons: Normal</p></li><li><p style="text-align: justify;">Hamstring muscles: Normal</p></li><li><p style="text-align: justify;">Hip flexors: Normal</p></li></ul><p style="text-align: justify;"><u>Neurovascular structures:</u>&nbsp; Normal</p><p style="text-align: justify;"><u>Pelvic Structures:</u></p><ul><li><p style="text-align: justify;">No visceral abnormality seen.</p></li><li><p style="text-align: justify;">Lymph nodes: Normal</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION</strong></p><p style="text-align: justify;"><strong>Normal hip MRI.</strong></p>`,

  "KNEE CT": `<p><strong>CT SCAN OF THE KNEE</strong></p><p><strong>TECHNIQUE:</strong><br>Axial images of the knee joint were obtained without intravenous contrast, with multiplanar reconstructions in coronal and sagittal planes. Bone and soft tissue algorithms were applied for evaluation.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Normal osseous features of the distal femur, proximal tibia, and fibula.</p></li><li><p>Normal osseous features of the patella with intact patellofemoral articulation.</p></li><li><p>Normal CT appearance of the medial and lateral menisci, including their anterior horns, bodies, and posterior horns.</p></li><li><p>Both cruciate ligaments appear intact on sagittal reconstruction.</p></li><li><p>No intra-articular dense loose bodies or fluid collections.</p></li><li><p>No abnormal juxta-articular soft tissue structures.</p></li></ul><p><strong>IMPRESSION:</strong><br>Essentially unremarkable non-contrast CT scan of the knee.</p>`,

  "KNEE MRI": `<p><strong>KNEE MRI</strong></p><p><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Multisequential multiplanar MRI of the knee was performed using a superconductive 1.5 Tesla magnet &amp; applying the knee coil.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><p style="text-align: justify;"><u>General:</u></p><ul><li><p style="text-align: justify;">Marrow:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Effusion:&nbsp; &nbsp;none</p></li><li><p style="text-align: justify;">Adequate trochlea groove and patella facet anatomy.</p></li></ul><p style="text-align: justify;"><u>Menisci:</u></p><ul><li><p style="text-align: justify;">Medial meniscus:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Lateral meniscus:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: justify;"><u>Ligaments and tendons:</u></p><ul><li><p style="text-align: justify;">Cruciate ligaments:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Medial collateral ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Lateral collateral ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Popliteofibular ligament:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Other posterolateral corner ligaments:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Popliteal tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Iliotibial band:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: justify;"><u>Extensor mechanism:</u></p><ul><li><p style="text-align: justify;">Quadriceps tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Patella:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Normal patella height (Normal Insall-Salvati ratio of 1.06).</p></li><li><p style="text-align: justify;">Patellar tendon:&nbsp; &nbsp;normal</p></li><li><p style="text-align: justify;">Hoffa’s fat pad:&nbsp; &nbsp;normal</p></li></ul><p style="text-align: justify;"><u>Cartilage:</u></p><ul><li><p style="text-align: justify;">Patellofemoral joint:&nbsp; &nbsp;normal cartilage</p></li><li><p style="text-align: justify;">Medial compartment:&nbsp; &nbsp;normal cartilage</p></li><li><p style="text-align: justify;">Lateral compartment:&nbsp; &nbsp;normal cartilage</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><p style="text-align: justify;"><strong>Normal knee MRI.&nbsp;</strong></p>`,

  "LL ANGIOGRAM": `<p><strong>LL ANGIOGRAM</strong></p><p><strong>FINDINGS</strong></p><ul><li><p>Normal course and caliber of the abdominal aorta showing no significant stenosis or occlusions.</p></li><li><p>Normal appearance of the major aortic visceral branches, with no significant stenosis.</p></li><li><p>Both common iliac arteries showed patent lumen with normal branching into external and internal iliac arteries, with no significantly stenotic segments.</p></li><li><p>Both common femoral arteries along with their deep branches are patent.</p></li></ul><p><strong>Right Lower Limb</strong></p><ul><li><p>Patent common, deep and superficial femoral arteries.</p></li><li><p>Patent popliteal artery.</p></li><li><p>The anterior tibial, posterior tibial and peroneal arteries are of normal</p></li><li><p>CT angiographic features with fair distal run-off.</p></li><li><p>The dorsalis pedis artery and deep plantar branches are patent.</p></li></ul><p><strong>Left Lower Limb</strong></p><ul><li><p>Patent common, deep and superficial femoral arteries.</p></li><li><p>Patent popliteal artery.</p></li><li><p>The anterior tibial, posterior tibial and peroneal arteries are of normal CT angiographic features with fair distal run-off.</p></li><li><p>The dorsalis pedis artery and deep plantar branches are patent.</p></li></ul><p><strong>IMPRESSION</strong></p><p>Normal Bilateral LL Angiogram</p>`,

  "LUMBAR SPINE MRI": `<p><strong>LUMBAR SPINE MRI</strong></p><p><strong>PROCEDURE:</strong><br>Multiplanar, multisequence MRI of the lumbar spine performed without intravenous contrast.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Lumbar lordosis is preserved. No scoliosis or spondylolisthesis.</p></li><li><p>Vertebral body heights, alignment, and marrow signal are within normal limits.</p></li><li><p>The conus medullaris demonstrates normal signal and morphology, terminating at the level of L1.</p></li><li><p>At all levels from L1/2 through L5/S1, the discs demonstrate normal signal and height, without evidence of bulge, herniation.&nbsp;</p></li><li><p>The spinal canal is widely patent with no thecal sac compromise.</p></li><li><p>Neural foramina are normal in caliber with free exit of nerve roots bilaterally.&nbsp;</p></li><li><p>Facet joints are unremarkable.</p></li><li><p>Normal appearance of ligamentum flavum.</p></li><li><p>Prevertebral, paravertebral soft tissues and visualized sacroiliac joints appear normal.</p></li></ul><p><strong>IMPRESSION:</strong><br>Normal MRI of the lumbar spine.</p>`,

  "LUMBOSACRAL SPINE": `<p><strong>LUMBOSACRAL SPINE RADIOGRAPH</strong></p><p><strong>TECHNIQUE:</strong></p><p>AP and lateral views of the lumbosacral spine.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Normal lumbar lordosis is maintained.&nbsp; No scoliosis.</p></li><li><p>The spinal alignment is maintained without evidence of spondylolisthesis.&nbsp;</p></li><li><p>The vertebral body and disc space heights are preserved.&nbsp;</p></li><li><p>No acute fracture is identified.&nbsp;</p></li><li><p>The SI joints are unremarkable.</p></li><li><p>The paravertebral soft tissues are normal.</p></li><li><p>The posterior elements are intact.</p></li></ul><p><strong>CONCLUSION&nbsp;</strong></p><p>Normal lumbosacral spine radiograph.</p>`,

  "MDCT BOTH PETROUS BONES": `<p><strong>MDCT OF BOTH PETROUS BONES</strong></p><p><strong>Indication:</strong></p><p><strong><u>Right side</u></strong></p><ul><li><p>Normal CT features of patent external auditory meatus.</p></li><li><p>The middle ear cavity including the ossicular chains is normal.</p></li><li><p>Normal pneumatization of the mastoid air cells.</p></li><li><p>Normal CT features of the Eustachian tube.</p></li><li><p>Normal CT features of the different segments of the facial canal.</p></li><li><p>Normal appearance of the internal auditory canal along with its structures showing normal dimensions and bony boundaries.&nbsp;</p></li><li><p>Intact falciform crest.</p></li><li><p>Normal appearance of the semicircular canals and cochlea.</p></li><li><p>Normal features of the visualized portion of the temporomandibular joint.</p></li></ul><p><strong><u>Left side</u></strong></p><ul><li><p>Normal CT features of patent external auditory meatus.</p></li><li><p>The middle ear cavity including the ossicular chains is normal.</p></li><li><p>Normal pneumatization of the mastoid air cells.</p></li><li><p>Normal CT features of the Eustachian tube.</p></li><li><p>Normal CT features of the different segments of the facial canal.</p></li><li><p>Normal appearance of the internal auditory canal along with its structures showing normal dimensions and bony boundaries.</p></li><li><p>Intact falciform crest.</p></li><li><p>Normal appearance of the semicircular canals and cochlea.</p></li><li><p>Normal features of the visualized portion of the temporomandibular joint</p></li></ul><p><strong><em><u>Otherwise:</u></em></strong></p><ul><li><p>Normal features of the cerebellopontine angles, posterior fossa structures including the pons and midbrain on non-contrast CT basis.</p></li><li><p>Normal appearance of the petrous bone including its apex.</p></li></ul><p><strong><em>Conclusion</em></strong></p><p>Normal CT temporal bone</p>`,

  MRCP: `<p><strong>MAGNETIC RESONANCE CHOLANGIOPANCREATOGRAPHY (MRCP)</strong></p><p><strong>TECHNIQUE:</strong><br>Multiplanar, multisequence MRI of the upper abdomen was performed, including heavily T2-weighted sequences for MRCP. No intravenous contrast was administered.</p><p><strong>FINDINGS:</strong></p><ul><li><p><strong>Liver:</strong> Normal size, contour, and signal intensity. No focal hepatic lesion.</p></li><li><p><strong>Gallbladder:</strong> Normal in size and configuration, without stones, wall thickening, or pericholecystic fluid.</p></li><li><p><strong>Biliary tree:</strong> Intrahepatic and extrahepatic bile ducts are normal in caliber. Common bile duct is of normal course and diameter, with smooth tapering to the ampulla. No evidence of choledocholithiasis, stricture, or mass.</p></li><li><p><strong>Pancreas:</strong> Normal size and signal intensity. Main pancreatic duct is normal in course and caliber, with no dilatation or filling defects.</p></li><li><p><strong>Spleen, adrenals, kidneys (visualized portions):</strong> Unremarkable.</p></li><li><p>No peritoneal free fluid or lymphadenopathy.</p></li></ul><p><strong>IMPRESSION</strong></p><p>Normal MRCP study.</p>`,

  "MRI BREAST": `<p><strong>BILATERAL BREAST MRI</strong></p><p><strong>PROCEDURE:</strong></p><p>Multiplanar multisequential MRI scans of both breasts are presented. IV contrast given.</p><p><strong>FINDINGS:</strong></p><ul><li><p>Both breasts are symmetrical in size with homogeneous fibroglandular signal seen bilaterally.</p></li><li><p>No discrete mass is seen in both breasts.</p></li><li><p>The glandular tissue demonstrates homogenously low signal on T1, moderately bright signal on T2 with fat saturation and homogenous enhancement post contrast.</p></li><li><p>There is no diffusion restriction.</p></li><li><p>Dynamic contrast scans show no areas of increased contrast uptake.</p></li><li><p>Overlying skin is normal and the chest wall unremarkable.</p></li><li><p>The nipples are normal with no retraction or retroareolar fibrosis.</p></li><li><p>Bilateral axillary subcentimetre benign lymph nodes are seen.</p></li><li><p>There is no intramammary lymphadenopathy.</p></li></ul><p><strong>CONCLUSION</strong></p><p><strong>No lesion or mass seen in both breasts.&nbsp;</strong></p><p><strong>BIRADS O: Ultrasound correlation.</strong></p>`,

  "MRI PELVIS FEMALE": `<p><strong>TECHNIQUE</strong></p><p>Multiplanar and multisequence MRI of the pelvis was performed without intravenous gadolinium contrast.</p><p><strong>FINDINGS</strong></p><ul><li><p>The uterus is normal in size, measuring … x … x …cm, with smooth and well-defined contours.</p></li><li><p>Myometrial signal intensity is uniform and normal across all sequences. No evidence of fibroids or other structural abnormalities.</p></li><li><p>The endometrial stripe is well-visualized, measuring … mm in thickness, with normal signal intensity.</p></li><li><p>The junctional zone appears intact and unremarkable.</p></li><li><p>Both ovaries are normal in size, morphology, and follicular distribution.</p></li><li><p>No adnexal masses, cysts, or other abnormalities are identified.</p></li><li><p>No free fluid is noted in the pouch of Douglas (POD) or other pelvic spaces.</p></li><li><p>No evidence of pelvic lymphadenopathy or mass lesions.</p></li><li><p>The urinary bladder is partially filled but demonstrates normal wall thickness and signal characteristics. No intraluminal or mural abnormalities are observed.</p></li><li><p>Both hip joints are normal, with no effusions or structural abnormalities.</p></li><li><p>The femoral heads exhibit normal morphology and signal intensity.</p></li><li><p>The sacroiliac joints and pubic symphysis appear normal without evidence of erosion or inflammation.</p></li><li><p>No significant incidental findings within the field of view.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p>Unremarkable MRI pelvis examination</p></li><li><p>No evidence of pelvic pathology.</p></li></ol>`,

  "NECK CT": `<p style="text-align: justify;"><strong>NECK CT SCAN</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Fine slice post IV contrast helical CT images were obtained from the skull base to the thoracic inlet. Soft tissue and bone windows were reconstructed.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><ul><li><p>The neck compartments are well demarcated with no evidence of a mass lesion.</p></li><li><p>The pharyngeal and glottic regions are normal. The parapharyngeal fat space is normal.&nbsp;</p></li><li><p style="text-align: justify;">The tonsils and adenoids are normal. The visualized nasal cavity is unremarkable.</p></li><li><p style="text-align: justify;">The parotid, submandibular and thyroid glands are normal.</p></li><li><p style="text-align: justify;">The muscles and tendons of the neck are within normal limits.</p></li><li><p style="text-align: justify;">There is no lymphadenopathy.&nbsp;</p></li><li><p style="text-align: justify;">No bony abnormality is seen. The cranio-cervical junction and spinal canal appear patent.</p></li><li><p style="text-align: justify;">The common carotids, carotid bulbs, internal carotid and external carotid arteries have a normal appearance. No evidence of atheroma, stenosis, aneurysm or dissection is seen.</p></li><li><p style="text-align: justify;">The jugular veins are normal.</p></li><li><p style="text-align: justify;">The lung apices are clear.</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><p style="text-align: justify;"><strong>Normal CT neck.</strong></p>`,

  "NECK MRI": `<p style="text-align: justify;"><strong>NECK MRI SCAN</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Multiplanar multisequential MRI of the neck are provided.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><ul><li><p>The nasopharynx is symmetrical without definite discrete infiltrating mass lesion.</p></li><li><p style="text-align: justify;">The parapharyngeal spaces are maintained.</p></li><li><p style="text-align: justify;">The retropharyngeal and masticator spaces are unremarkable.</p></li><li><p style="text-align: justify;">The oropharynx, hypopharynx, larynx, thyroid, submandibular and parotid glands are normal.</p></li><li><p style="text-align: justify;">The carotid-jugular complex on both sides is undisturbed.</p></li><li><p style="text-align: justify;">No definite evidence of enlarged lymph nodes. The airway is patent and midline in location.</p></li><li><p style="text-align: justify;">The visualised paranasal sinuses and both mastoids are clear.</p></li><li><p style="text-align: justify;">No abnormal bone marrow changes are appreciated.</p></li><li><p style="text-align: justify;">Cervical spine intervertebral discs are normal in height and signal intensity.</p></li><li><p style="text-align: justify;">Spinal cord is normal in size and signal intensity.</p></li><li><p style="text-align: justify;">Free exit of nerve roots bilaterally.</p></li><li><p style="text-align: justify;">Brachial plexi show normal signal intensity and thickness.</p></li><li><p style="text-align: justify;">Normal cranio-cervical junction.</p></li></ul><p style="text-align: justify;"><strong>IMPRESSION</strong></p><p style="text-align: justify;"><strong>Normal neck MRI&nbsp;</strong></p>`,

  "PELVIC X-RAY": `<p><strong>PELVIC X-RAY</strong></p><p><strong>TECHNIQUE</strong>: AP view of the pelvis. </p><p><strong>FINDINGS </strong></p><ul><li><p>The pelvic ring is normal.</p></li><li><p>Normal shape and size of femoral heads.</p></li><li><p>Iliac and sacral bones are intact.</p></li><li><p>No fracture or dislocation is seen.</p></li><li><p>The hips joints and symphysis pubis are normal.</p></li><li><p>Both sacroiliac joints are normal.</p></li></ul><p><strong>CONCLUSION</strong></p><p>No osseous or articular abnormalities of the pelvis.</p>`,

  "PNS CT": `<p style="text-align: justify;"><strong>PARANASAL SINUSES CT</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Fine slice non-contrast helical CT images were obtained through the paranasal sinuses. Bone and soft tissue windows were reconstructed.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><ul><li><p>The paranasal sinuses are clear, with no mucoperiosteal thickening, mucous retention cysts or air-fluid levels.</p></li><li><p style="text-align: justify;">The osteomeatal complexes have a normal appearance and no abnormal air cells are identified.</p></li><li><p style="text-align: justify;">The nasal septum is midline with no spur.</p></li><li><p style="text-align: justify;">The nasal conchae are normal with smooth mucosa and no aeration.</p></li><li><p style="text-align: justify;">The orbits have a normal appearance, as does the nasopharynx and visualized oropharynx.</p></li><li><p style="text-align: justify;">No bony abnormality is seen. The alveolar rim of the maxilla is normal.</p></li><li><p style="text-align: justify;">No soft tissue abnormality is seen.</p></li></ul><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><p style="text-align: justify;"><strong>Normal CT paranasal sinuses.</strong></p>`,

  "PNS RADIOGRAPH": `<p><strong>PNS RADIOGRAPH</strong></p><p><strong>Clinical Note:</strong> Rule out adenoid hypertrophy.</p><p><strong>FINDINGS</strong></p><ul><li><p>The post-nasal air space is well maintained with normal-sized adenoid tissue.&nbsp;</p></li><li><p>The soft palate, nasal septum, and bony structures appear normal.</p></li></ul><p><strong>IMPRESSION</strong></p><ol><li><p><strong>Normal post-nasal space. No radiographic evidence of adenoidal hypertrophy.</strong></p></li></ol>`,

  "PROSTATE MRI": `<p><strong>PROSTATE MRI</strong></p><p style="text-align: justify;"><strong>TECHNIQUE</strong></p><p style="text-align: justify;">Multiparametric multiplanar MRI of the prostate was performed using a 1.5 Tesla MRI system. IV gadolinium-based contrast administered.</p><p style="text-align: justify;"><strong>FINDINGS</strong></p><ul><li><p>The prostate gland is normal in size and configuration, with an estimated volume of approximately …. mls. The zonal anatomy is well preserved. The peripheral zone demonstrates homogeneous high signal intensity on T2-weighted images, with no focal lesions, no areas of restricted diffusion on DWI or ADC maps, and no abnormal or early enhancement on DCE sequences. The transition zone appears normal in texture and symmetry, with no evidence of low T2 signal nodules or suspicious features.</p></li><li><p>There is no evidence of extra-prostatic extension, capsular irregularity, or seminal vesicle invasion. The seminal vesicles are symmetric and demonstrate normal morphology and signal characteristics. The neurovascular bundles are preserved bilaterally. There is no pelvic lymphadenopathy, and the visualized portions of the urinary bladder and rectum are unremarkable.</p></li></ul><p style="text-align: justify;"><strong>IMPRESSION</strong></p><p style="text-align: justify;">Overall, no suspicious lesions are identified within the prostate. PI-RADS 1.</p>`,

  "RIGHT SHOULDER MRI": `<p style="text-align: left;"><strong>RIGHT SHOULDER MRI</strong></p><p style="text-align: left;"><strong>TECHNIQUE:</strong></p><p style="text-align: left;">Multiplane multisequential MRI of the right shoulder. No IV or intra-articular contrast given.</p><p style="text-align: left;"><strong>FINDINGS:</strong></p><ul><li><p style="text-align: left;"><strong>Rotator Cuff:</strong>&nbsp;The right supraspinatus, infraspinatus, subscapularis and teres minor tendons have a normal appearance with no evidence of tear or tendinopathy.</p></li><li><p style="text-align: left;"><strong>Muscles:</strong>&nbsp; No significant fatty infiltration of the supraspinatus muscle. No muscle atrophy with negative tangent sign.</p></li><li><p style="text-align: left;"><strong>Biceps:</strong>&nbsp; The tendon is normally located in the bicipital groove,&nbsp;till its anchor into the superior glenoid. No fluid around the it. The short head of biceps is normal, with unremarkable coracoid process attachment.</p></li><li><p style="text-align: left;"><strong>Rotator Cuff Interval:</strong>&nbsp;&nbsp;Normal, with no thickening of the soft tissue or abnormality of the coracoclavicular or coracohumeral ligaments.&nbsp;</p></li><li><p style="text-align: left;">The intra-articular component of the long head of biceps is normal.</p></li><li><p style="text-align: left;"><strong>Subacromial/Subdeltoid Bursa</strong>:&nbsp;&nbsp;No fluid effusion.</p></li><li><p style="text-align: left;"><strong>Acromion/AC joint:</strong>&nbsp;&nbsp;There is a type 1 acromion. No degenerative changes seen.</p></li><li><p style="text-align: left;"><strong>Glenohumeral Joint/Labrum:</strong>&nbsp;&nbsp;The glenoid labrum has a normal appearance, as does the glenoid and humeral head cartilage.&nbsp;</p></li><li><p style="text-align: left;">No definite labral tear or chondromalacia.&nbsp;Glenohumeral joint effusion.</p></li><li><p style="text-align: left;">The glenohumeral ligaments are unremarkable.</p></li><li><p style="text-align: left;">The capsule has a normal appearance. No loose bodies are identified.</p></li><li><p style="text-align: left;"><strong>Bone Marrow:</strong>&nbsp;&nbsp;benign marrow transformation.</p></li></ul><p style="text-align: left;">Normal MRI features of the proximal humerus. No fracture or depression seen.</p><p style="text-align: left;"><strong>CONCLUSION:</strong></p><p style="text-align: left;"><strong>Normal right shoulder MRI scan.</strong></p><p style="text-align: left;"><strong>No tendon, ligamentous or labral lesion seen.</strong></p>`,

  "RIGHT MAMMOGRAM": `<p><strong>RIGHT BREAST MAMMOGRAM</strong></p><p><strong>TECHNIQUE:</strong></p><p>Standard right craniocaudal (CC) and mediolateral oblique (MLO) views were obtained.</p><p>Images are of adequate quality with good compression and positioning.</p><p><strong>FINDINGS</strong></p><ul><li><p>The breasts show scattered fibroglandular densities.</p></li><li><p>No discrete mass lesion, architectural distortion, or suspicious asymmetry identified.</p></li><li><p>No new focal density or spiculated lesion seen.</p></li><li><p>No suspicious microcalcifications or grouped calcifications identified.</p></li><li><p>No skin thickening, nipple retraction, or subareolar abnormality noted.</p></li><li><p>No axillary lymphadenopathy or abnormal soft tissue density.</p></li></ul><p><strong>IMPRESSION</strong></p><p>Normal right breast mammogram.</p><p>BI-RADS Category 1 – Negative.</p>`,

  "THORACIC SPINE MRI": `<p><strong>THORACIC SPINE MRI</strong></p><p><strong>TECHNIQUE</strong></p><p>Sagittal T1/T2 and STIR and axial T2WI of the thoracic spine MRI scans are presented.</p><p><strong>FINDINGS</strong></p><ul><li><p>Adequate alignment of the dorsal spine, with no signs of instability detected.</p></li><li><p>Maintained normal height of the vertebral bodies, Normal posterior elements.</p></li><li><p>Normal bony texture of the dorsal vertebrae, with no focal lesions identified.</p></li><li><p>No significant disc bulges or herniations seen, with no cord compromise visualized.</p></li><li><p>Normal size and signal of the dorsal cord, with no foci of abnormal signal intensity seen.</p></li><li><p>Normal pre and paravertebral soft tissue shadow.</p></li></ul><p><strong>IMPRESSION</strong></p><p><strong>Normal thoracic spine MRI.</strong></p>`,

  "UPPER LIMB CT ANGIOGRAM": `<p><strong>UPPER LIMB CT ANGIOGRAM&nbsp;</strong></p><p><strong>TECHNIQUE:</strong><br>The upper limb arteries were evaluated from the hands to the heart.</p><p>Multi-axial and 3D reconstruction images are presented for reporting.</p><p><strong>FINDINGS:</strong></p><ul><li><p>No suspicious osseous lesion is seen.</p></li><li><p>The lungs, brain, head and neck are unremarkable.</p></li><li><p>The heart, aorta, IVC and central major vessels are normal.</p></li><li><p>The ascending aorta, arch of aorta, brachiocephalic trunk, common carotid and subclavian arteries are normal bilaterally.</p></li><li><p>The axillary, brachial, radial, ulnar and interosseous arteries are well demonstrated with good contrast opacification bilaterally.</p></li><li><p>The superficial and deep palmar arches are normal.</p></li><li><p>The common palmar digital branches are well opacified by contrast.</p></li><li><p>The proper digital branches are well outlined by contrast bilaterally.</p></li><li><p>No atheromatous plaques or intraluminal filling defects are seen.</p></li></ul><p><strong>CONCLUSION&nbsp;</strong></p><p>NORMAL UPPER LIMB CT ANGIOGRAM</p>`,

  "WHOLE SPINE MOBIVIEW": `<p style="text-align: left;"><strong>1. CERVICAL SPINE</strong></p><p style="text-align: left;"><strong>TECHNIQUE</strong></p><p style="text-align: left;">Sagittal T2wi images of the cervical spine. No IV contrast was given.<br><strong>FINDINGS</strong></p><ul><li><p style="text-align: left;">Straightening of the cervical spine. No spondylolisthesis or scoliosis.</p></li><li><p style="text-align: left;">Normal height and signal intensity of the cervical vertebral bodies. Posterior elements are normal.</p></li><li><p style="text-align: left;">Normal marrow signal of the cervical vertebrae, with no focal lesions identified.</p></li><li><p style="text-align: left;">No significant disc bulges or herniations seen, with no cord or foraminal compromise visualized.</p></li><li><p style="text-align: left;">Normal shape, girth and intensity of the cervical cord, with no cervico-medullary junction abnormalities noted.</p></li><li><p style="text-align: left;">No bony canal tightness observed.</p></li><li><p style="text-align: left;">Normal pre and paravertebral soft tissue shadow.</p></li></ul><p style="text-align: left;"><strong>IMPRESSION</strong></p><p style="text-align: left;"><strong>Normal cervical spine MRI.</strong></p><br><p><strong>2. DORSAL SPINE MRI</strong></p><p style="text-align: left;"><strong>TECHNIQUE</strong></p><p style="text-align: left;">Sagittal T2wi images of the thoracic spine. No IV contrast was given.</p><p style="text-align: left;"><strong>FINDINGS</strong></p><ul><li><p style="text-align: left;">Adequate alignment of the dorsal spine, with no signs of instability detected.</p></li><li><p style="text-align: left;">Normal bony texture of the dorsal vertebrae, with no focal lesions identified.</p></li><li><p style="text-align: left;">No significant disc bulges or herniations seen, with no cord compromise visualized.</p></li><li><p style="text-align: left;">Normal size and signal of the dorsal cord, with no foci of abnormal signal intensity seen.</p></li><li><p style="text-align: left;">No bony canal tightness seen.</p></li><li><p style="text-align: left;">Normal pre and paravertebral soft tissue shadow.</p></li></ul><p style="text-align: left;"><strong>IMPRESSION</strong></p><p style="text-align: left;"><strong>Normal thoracic spine MRI.</strong></p><br><p><strong>3. LUMBOSACRAL SPINE</strong></p><p style="text-align: left;"><strong>TECHNIQUE</strong></p><p style="text-align: left;">Sagittal T1/T2 and STIR and axial T2 images of the lumbar spine. No IV contrast was given.<br><strong>FINDINGS</strong></p><ul><li><p style="text-align: left;">Maintained normal lumbar spine lordosis.&nbsp;No scoliosis or spondylolisthesis.&nbsp;</p></li><li><p style="text-align: left;">Normal vertebral body height and alignment.&nbsp; Bone marrow is normal in signal throughout.&nbsp;</p></li><li><p style="text-align: left;">Normal appearances and configuration of the conus medullaris terminating at L1.&nbsp;&nbsp;</p></li><li><p style="text-align: left;">The spinal canal is normal with no crowding nerve roots seen.</p></li><li><p style="text-align: left;">At L1/2 level, Normal disc signal with no bulge or herniation. No&nbsp;neural or spinal canal compromise. Normal facet joints.</p></li><li><p style="text-align: left;">At L2/3 level, Normal disc signal with no bulge or herniation. No&nbsp;neural or spinal canal compromise. Normal facet joints.</p></li><li><p style="text-align: left;">At L3/4 level, Normal disc signal with no bulge or herniation. No&nbsp;neural or spinal canal compromise. Normal facet joints.</p></li><li><p style="text-align: left;">At L4/5 level Normal disc signal with no bulge or herniation. No&nbsp;neural or spinal canal compromise. Normal facet joints.</p></li><li><p style="text-align: left;">At L5/S1 level, Normal disc signal with no bulge or herniation. No&nbsp;neural or spinal canal compromise. Normal facet joints.</p></li><li><p style="text-align: left;">Pre and paravertebral soft tissues are normal.</p></li></ul><p style="text-align: left;"><strong>IMPRESSION</strong></p>`,

  "WRIST MRI": `<p style="text-align: justify;"><strong>WRIST MRI SCAN</strong></p><p style="text-align: justify;"><strong>TECHNIQUE:</strong></p><p style="text-align: justify;">Multiplane multisequential wrist MRI scan images were obtained using a 1.5T close magnet machine.</p><p style="text-align: justify;"><strong>FINDINGS:</strong></p><p style="text-align: justify;"><u>Alignment:</u></p><ul><li><p style="text-align: justify;">Ulnar variance: none</p></li><li><p style="text-align: justify;">Distal radioulnar joint: normal</p></li><li><p style="text-align: justify;">Carpal instability: none</p></li></ul><p style="text-align: justify;"><u>Fluid:</u></p><ul><li><p style="text-align: justify;">Carpus effusion: none</p></li><li><p style="text-align: justify;">Distal radioulnar joint effusion: none</p></li></ul><p style="text-align: justify;"><u>Intrinsic Ligaments:</u></p><ul><li><p style="text-align: justify;">Scapholunate ligament: normal</p></li><li><p style="text-align: justify;">Lunotriquetral ligament: normal</p></li><li><p style="text-align: justify;">Triangular fibrocartilage: normal. No evidence of tear or perforation.</p></li></ul><p style="text-align: justify;"><u>Joints:</u></p><ul><li><p style="text-align: justify;">Distal radioulnar joint: normal</p></li><li><p style="text-align: justify;">Radiocarpal Joint: normal</p></li><li><p style="text-align: justify;">Intercarpal joints: normal</p></li><li><p style="text-align: justify;">Carpometacarpal joints: normal</p></li><li><p style="text-align: justify;">Lunate facet: absent</p></li><li><p style="text-align: justify;">Hamate-lunate facet: normal</p></li><li><p style="text-align: justify;">Synovium: normal</p></li></ul><p style="text-align: justify;"><u>Tendons:</u></p><ul><li><p style="text-align: justify;">Flexor tendons: normal</p></li><li><p style="text-align: justify;">Extensor tendons: normal</p></li><li><p style="text-align: justify;">Extensor Carpi Ulnaris: normal</p></li></ul><p style="text-align: justify;"><u>Flexor Compartments:</u></p><ul><li><p style="text-align: justify;">Carpal tunnel: normal</p></li><li><p style="text-align: justify;">Median nerve: normal</p></li><li><p style="text-align: justify;">Flexor retinaculum: normal</p></li><li><p style="text-align: justify;">Guyon’s canal: normal</p></li></ul><p style="text-align: justify;"><strong>Bones</strong>:&nbsp;normal. No fracture or bone marrow edema.</p><p style="text-align: justify;"><strong>Muscles</strong>:&nbsp;normal</p><p style="text-align: justify;"><strong>Vessels and nerves</strong>:&nbsp;normal</p><p style="text-align: justify;"><strong>Miscellaneous:</strong>&nbsp;No dorsal or volar ganglion cysts identified.</p><p style="text-align: justify;"><strong>CONCLUSION:</strong></p><ol><li><p style="text-align: justify;"><strong>Triangular fibrocartilage is intact</strong></p></li><li><p style="text-align: justify;"><strong>No bony or joint abnormality identified</strong></p></li><li><p style="text-align: justify;"><strong>Normal flexor and extensor structures</strong></p></li><li><p style="text-align: justify;"><strong>No ganglion cyst</strong></p></li></ol>`,

  "WRIST RADIOGRAPH": `<p><strong>WRIST RADIOGRAPH (AP and Lateral Views)</strong></p><p><strong>FINDINGS</strong></p><ul><li><p>The bony alignment is normal. No fracture, dislocation, or bone destruction is seen.</p></li><li><p>The joint spaces are well preserved.</p></li><li><p>No periosteal reaction or soft tissue swelling is noted.</p></li></ul><p><strong>IMPRESSION</strong></p><p><strong>Normal wrist radiograph.</strong></p>`,
};

export default templates;
